<template><div class="page dimension-page">
 <div class="page-header"><div><div class="page-title">设备分析维度</div><div class="hint">按生效日期维护设备归属，历史用量将按当天有效归属统计</div></div><el-button v-if="canEdit" type="primary" @click="openDimension()">新增维度</el-button></div>
 <el-row :gutter="14"><el-col :xs="24" :md="7"><el-card class="side-card"><template #header><b>分析维度</b></template><div v-for="d in dimensions" :key="d.id" class="dimension-item" :class="{active:dimensionId===d.id}" @click="chooseDimension(d)"><span>{{d.dimension_name}}<small>{{d.dimension_code}}</small></span><el-dropdown v-if="canEdit" @command="(c:string)=>dimensionCommand(c,d)" @click.stop><span>•••</span><template #dropdown><el-dropdown-menu><el-dropdown-item command="edit">编辑</el-dropdown-item><el-dropdown-item command="delete" divided>删除</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></el-card>
 <el-card v-if="currentDimension" class="side-card value-card"><template #header><div class="card-title"><b>{{currentDimension.dimension_name}}分类</b><el-button v-if="canEdit" link type="primary" @click="openValue()">新增</el-button></div></template><div class="value-item" :class="{active:!filters.valueId&&!filters.unassigned}" @click="chooseValue()"><span>全部分类</span></div><div class="value-item" :class="{active:filters.unassigned}" @click="chooseUnassigned">未设置</div><div v-for="v in currentDimension.values||[]" :key="v.id" class="value-item" :class="{active:filters.valueId===v.id}" @click="chooseValue(v.id)"><span><i :style="{background:v.color}"/>{{v.value_name}}</span><span>{{v.device_count||0}} <el-dropdown v-if="canEdit" @command="(c:string)=>valueCommand(c,v)" @click.stop><b>•••</b><template #dropdown><el-dropdown-menu><el-dropdown-item command="edit">编辑</el-dropdown-item><el-dropdown-item command="delete" divided>删除</el-dropdown-item></el-dropdown-menu></template></el-dropdown></span></div></el-card></el-col>
 <el-col :xs="24" :md="17"><el-card><div class="toolbar"><el-date-picker v-model="filters.effectiveDate" type="date" value-format="YYYY-MM-DD" placeholder="查看日期" @change="loadDevices"/><el-input v-model="filters.keyword" clearable placeholder="设备名称、编号、表号或通讯地址" @keyup.enter="loadDevices"/><el-select v-model="filters.energyType" clearable placeholder="能源类型"><el-option label="电" value="ELECTRIC"/><el-option label="水" value="WATER"/><el-option label="气" value="GAS"/></el-select><el-button @click="loadDevices">查询</el-button></div><div v-if="canEdit" class="assign-bar"><el-select v-model="assignValueId" placeholder="设置为分类"><el-option v-for="v in activeValues" :key="v.id" :label="v.value_name" :value="v.id"/></el-select><el-date-picker v-model="effectiveFrom" type="date" value-format="YYYY-MM-DD" placeholder="归属生效日期"/><el-button type="primary" :disabled="!selected.length||!assignValueId||!effectiveFrom" @click="assign">应用到已选 {{selected.length}} 台</el-button><span>生效日前用量保留在原分类，生效日开始计入新分类</span></div><el-table :data="devices" v-loading="loading" border row-key="platform_device_id" @selection-change="selected=$event"><el-table-column v-if="canEdit" type="selection" width="44"/><el-table-column prop="device_name" label="设备" min-width="180" show-overflow-tooltip/><el-table-column prop="comm_address" label="通讯地址" width="120"/><el-table-column prop="serial_number" label="表号" width="145"/><el-table-column prop="energy_type_name" label="类型" width="80"/><el-table-column label="当前分类" min-width="120"><template #default="{row}"><el-tag v-if="row.value_name" :color="row.color" effect="dark">{{row.value_name}}</el-tag><span v-else class="muted">未设置</span></template></el-table-column><el-table-column label="有效期" min-width="190"><template #default="{row}">{{row.effective_from||'-'}} 至 {{row.effective_to||'长期'}}</template></el-table-column><el-table-column label="操作" width="80"><template #default="{row}"><el-button link type="primary" @click="showHistory(row)">历史</el-button></template></el-table-column></el-table><div class="count">共 {{devices.length}} 台设备</div></el-card></el-col></el-row>
 <el-dialog v-model="edit.visible" :title="edit.kind==='dimension'?(edit.id?'编辑维度':'新增维度'):(edit.id?'编辑分类':'新增分类')" width="440px"><el-form label-width="90px"><template v-if="edit.kind==='dimension'"><el-form-item label="维度名称"><el-input v-model="edit.form.dimensionName" placeholder="例如：楼层、部门"/></el-form-item><el-form-item label="维度编码"><el-input v-model="edit.form.dimensionCode" placeholder="例如：FLOOR、DEPARTMENT"/></el-form-item></template><template v-else><el-form-item label="分类名称"><el-input v-model="edit.form.valueName"/></el-form-item><el-form-item label="分类编码"><el-input v-model="edit.form.valueCode"/></el-form-item><el-form-item label="显示颜色"><el-color-picker v-model="edit.form.color"/></el-form-item></template><el-form-item label="排序"><el-input-number v-model="edit.form.sortOrder" :min="0"/></el-form-item><el-form-item label="状态"><el-switch v-model="edit.form.status" :active-value="1" :inactive-value="0"/></el-form-item><el-form-item label="备注"><el-input v-model="edit.form.remark" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="edit.visible=false">取消</el-button><el-button type="primary" @click="saveEdit">保存</el-button></template></el-dialog>
 <el-dialog v-model="historyVisible" title="设备归属历史" width="620px"><el-table :data="history" border><el-table-column prop="value_name" label="分类"/><el-table-column prop="effective_from" label="生效日期" width="120"/><el-table-column label="结束日期" width="120"><template #default="{row}">{{row.effective_to||'长期'}}</template></el-table-column></el-table></el-dialog>
</div></template>
<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{energyApi}from'@/api/energy';import{useUserStore}from'@/stores/user';
const today=()=>new Date().toISOString().slice(0,10),userStore=useUserStore(),canEdit=computed(()=>userStore.user?.roles?.some(r=>['SUPER_ADMIN','SYSTEM_ADMIN'].includes(r)));const dimensions=ref<any[]>([]),dimensionId=ref<number>(),devices=ref<any[]>([]),selected=ref<any[]>([]),assignValueId=ref<number>(),effectiveFrom=ref(today()),loading=ref(false),historyVisible=ref(false),history=ref<any[]>([]);const filters=reactive<any>({effectiveDate:today(),keyword:'',energyType:'',valueId:undefined,unassigned:false});const edit=reactive<any>({visible:false,kind:'dimension',id:null,form:{}});const currentDimension=computed(()=>dimensions.value.find(d=>d.id===dimensionId.value));const activeValues=computed(()=>(currentDimension.value?.values||[]).filter((v:any)=>v.status===1));
async function loadDimensions(){dimensions.value=await energyApi.dimensions() as any;if(!dimensionId.value&&dimensions.value.length)dimensionId.value=dimensions.value[0].id}async function loadDevices(){if(!dimensionId.value)return;loading.value=true;try{devices.value=await energyApi.dimensionDevices(dimensionId.value,{effectiveDate:filters.effectiveDate,keyword:filters.keyword||undefined,energyType:filters.energyType||undefined,valueId:filters.valueId,unassigned:filters.unassigned||undefined}) as any}finally{loading.value=false}}function chooseDimension(d:any){dimensionId.value=d.id;filters.valueId=undefined;filters.unassigned=false;assignValueId.value=undefined;loadDevices()}function chooseValue(id?:number){filters.valueId=id;filters.unassigned=false;loadDevices()}function chooseUnassigned(){filters.valueId=undefined;filters.unassigned=true;loadDevices()}
function openDimension(d?:any){edit.kind='dimension';edit.id=d?.id||null;edit.form={dimensionName:d?.dimension_name||'',dimensionCode:d?.dimension_code||'',sortOrder:d?.sort_order||0,status:d?.status??1,remark:d?.remark||''};edit.visible=true}function openValue(v?:any){edit.kind='value';edit.id=v?.id||null;edit.form={valueName:v?.value_name||'',valueCode:v?.value_code||'',color:v?.color||'#409EFF',sortOrder:v?.sort_order||0,status:v?.status??1,remark:v?.remark||''};edit.visible=true}async function saveEdit(){if(edit.kind==='dimension'){if(!edit.form.dimensionName||!edit.form.dimensionCode)return ElMessage.warning('请填写维度名称和编码');edit.id?await energyApi.updateDimension(edit.id,edit.form):await energyApi.createDimension(edit.form)}else{if(!edit.form.valueName||!edit.form.valueCode)return ElMessage.warning('请填写分类名称和编码');edit.id?await energyApi.updateDimensionValue(edit.id,edit.form):await energyApi.createDimensionValue(dimensionId.value!,edit.form)}edit.visible=false;ElMessage.success('已保存');await loadDimensions();await loadDevices()}async function dimensionCommand(c:string,d:any){if(c==='edit')return openDimension(d);await ElMessageBox.confirm(`确认删除维度“${d.dimension_name}”？已有归属历史的维度不能删除。`,'删除维度',{type:'warning'});await energyApi.deleteDimension(d.id);if(dimensionId.value===d.id)dimensionId.value=undefined;await loadDimensions();await loadDevices()}async function valueCommand(c:string,v:any){if(c==='edit')return openValue(v);await ElMessageBox.confirm(`确认删除分类“${v.value_name}”？已有归属历史的分类不能删除。`,'删除分类',{type:'warning'});await energyApi.deleteDimensionValue(v.id);await loadDimensions();await loadDevices()}
async function assign(){await energyApi.assignDimension({dimensionId:dimensionId.value,dimensionValueId:assignValueId.value,effectiveFrom:effectiveFrom.value,deviceIds:selected.value.map(x=>x.platform_device_id)});ElMessage.success('设备归属已按生效日期更新');filters.effectiveDate=effectiveFrom.value;await loadDimensions();await loadDevices()}async function showHistory(row:any){history.value=await energyApi.dimensionHistory(dimensionId.value!,row.platform_device_id) as any;historyVisible.value=true}onMounted(async()=>{await loadDimensions();await loadDevices()});
</script>
<style scoped>.page{padding:18px}.page-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.page-title{font-size:22px;font-weight:700}.hint,.muted,.count{color:#909399;font-size:13px}.side-card{margin-bottom:14px}.dimension-item,.value-item,.card-title{display:flex;justify-content:space-between;align-items:center}.dimension-item,.value-item{padding:10px;border-radius:6px;cursor:pointer}.dimension-item.active,.value-item.active{background:#ecf5ff;color:#409eff}.dimension-item small{display:block;color:#909399;font-size:10px;margin-top:2px}.value-item i{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:7px}.toolbar,.assign-bar{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:12px}.toolbar .el-input{width:280px}.toolbar .el-select{width:130px}.assign-bar{background:#f4f8fc;padding:10px;border-radius:6px}.assign-bar>span{font-size:12px;color:#909399}.count{text-align:right;margin-top:10px}@media(max-width:768px){.page{padding:10px}.toolbar,.assign-bar{align-items:stretch;flex-direction:column}.toolbar>*,.assign-bar>*{width:100%!important}.side-card{margin-bottom:10px}}</style>
